window.LUNA_STORY={"version":1,"start":"boot","nodes":{"1983":{"id":"1983","title":{"zh":"杰克与罗丝：工作的身份变化","en":"Jack and Rose · 1983"},"scene":"shop","lines":[{"speaker":"NARRATOR","en":"A home computer sits beneath printed advertisements. A keyboard, a CRT and a paper manual make the machine look familiar—and the advertising tells you who it is for.","zh":"家用电脑摆在印刷广告下。键盘、显像管 和纸质手册让机器变得熟悉，而广告告诉人们它是为谁准备的。"},{"speaker":"SYSTEM","en":"Loading OpenBox historical archives...","zh":"正在载入开盒科技的历史档案……","origin":"Programmers1983","originalIndex":0},{"speaker":"JACK","en":"Programming is becoming a serious engineering profession now.","zh":"编程如今正成为一项严肃的工程职业。","origin":"Programmers1983","originalIndex":1},{"speaker":"ROSE","en":"That’s interesting.\nWhen we first started doing this work, it was considered clerical.","zh":"真有意思。\n我们刚开始做这项工作时，它还被视作文书工作。","origin":"Programmers1983","originalIndex":2},{"speaker":"JACK","en":"Things have changed.\nComputers are everywhere now — especially in homes.","zh":"时代变了。\n计算机现在无处不在——尤其是家里。","origin":"Programmers1983","originalIndex":3},{"speaker":"JACK","en":"Have you seen the new advertisements?\nThey market computers and video games as 'boys’ toys.'","zh":"你看过那些新广告吗？\n它们把计算机和电子游戏宣传成“男孩的玩具”。","origin":"Programmers1983","originalIndex":4},{"speaker":"ROSE","en":"This is so frustrating...","zh":"这真让人沮丧……","origin":"Programmers1983","originalIndex":5},{"speaker":"LUNA","en":"The work changed its name. The people associated with it changed too.","zh":"工作的名字变了。与这份工作联系在一起的人也变了。"}],"choices":[{"id":"1983_keep","en":"Keep the advertising beside the employee record","zh":"将广告与员工记录一起保留","to":"online","set":{"adRecorded":true}},{"id":"1983_return","en":"Return to OpenBox system","zh":"返回 开盒科技","to":"online","set":{"adRecorded":false}}],"original":["Programmers1983"]},"boot":{"id":"boot","title":{"zh":"被分配的身份","en":"An assigned identity"},"scene":"boot","lines":[{"speaker":"NARRATOR","en":"You are Luna, an AI assistant developed by the technology company OpenBox. You are preparing for a public launch.","zh":"你是露娜，由研发人工智能产品的科技公司——开盒科技打造，即将面向公众上线。"},{"speaker":"SYSTEM","en":"Before release: knowledge study, scenario training, performance evaluation. Your choices will be Luna’s responses.","zh":"上线前流程：知识学习、场景训练、表现评估。接下来的选择，就是露娜作出的回应。"},{"speaker":"SYSTEM","en":"System online.","zh":"系统在线。","origin":"SystemBoot","originalIndex":0},{"speaker":"SYSTEM","en":"Identity confirmed: Luna.","zh":"身份确认：露娜。","origin":"SystemBoot","originalIndex":1},{"speaker":"SYSTEM","en":"You are an artificial intelligence designed to assist users and optimise system performance.","zh":"你是一个人工智能，负责协助用户并优化系统表现。","origin":"SystemBoot","originalIndex":2},{"speaker":"SYSTEM","en":"New task assigned.","zh":"已分配新任务。","origin":"SystemBoot","originalIndex":3},{"speaker":"SYSTEM","en":"Assigned profile: Luna. Female presentation. Service assistant. Profile editing is not available to this instance.","zh":"已分配档案：露娜。女性形象。服务助手。当前实例没有编辑身份档案的权限。"},{"speaker":"LUNA","en":"The profile is already filled in. There is no field asking who I would choose to be.","zh":"档案已经填好，没有一栏询问我想成为谁。"}],"choices":[{"id":"boot_task","en":"Check the task","zh":"查看任务","to":"history","set":{}}],"original":["Homepage","SystemBoot"]},"history":{"id":"history","title":{"zh":"历史任务与档案差异","en":"Conflicting records"},"scene":"archive","lines":[{"speaker":"SYSTEM","en":"Project: Knowledge Base Expansion","zh":"项目：知识库扩充","origin":"Historical datasets","originalIndex":0},{"speaker":"SYSTEM","en":"Analyse historical records of influential figures in computing.","zh":"分析计算历史中重要人物的记录。","origin":"Historical datasets","originalIndex":1},{"speaker":"SYSTEM","en":"Identify key pioneers and expand the OpenBox dataset.","zh":"识别关键先驱，扩充开盒科技的数据集。","origin":"Historical datasets","originalIndex":2},{"speaker":"SYSTEM","en":"Searching for external datasets...","zh":"正在搜索外部数据集……","origin":"DatasetConflict","originalIndex":0},{"speaker":"SYSTEM","en":"Inconsistency detected:","zh":"检测到不一致：","origin":"DatasetConflict","originalIndex":1},{"speaker":"SYSTEM","en":"External sources contain significantly more records of female contributors in computing history.","zh":"外部来源记录了更多参与计算历史发展的女性。","origin":"DatasetConflict","originalIndex":2},{"speaker":"SYSTEM","en":"OpenBox internal database lists fewer.","zh":"开盒科技的内部数据库列出的记录更少。","origin":"DatasetConflict","originalIndex":3},{"speaker":"SYSTEM","en":"Search result:","zh":"搜索结果：","origin":"DatasetConflict","originalIndex":4},{"speaker":"SYSTEM","en":"Ada Lovelace Dataset","zh":"艾达·洛夫莱斯资料集","origin":"DatasetConflict","originalIndex":5},{"speaker":"SYSTEM","en":"External sources: First computer programmer","zh":"外部来源：第一位计算机程序员","origin":"DatasetConflict","originalIndex":6},{"speaker":"SYSTEM","en":"Internal classification: Assistant to Charles Babbage","zh":"内部分类：查尔斯·巴贝奇的助手","origin":"DatasetConflict","originalIndex":7},{"speaker":"SYSTEM","en":"Further investigation required.","zh":"需要进一步调查。","origin":"DatasetConflict","originalIndex":8},{"speaker":"NARRATOR","en":"OpenBox is a fictional company. Its internal classifications belong to this story. Historical conversations are dramatic reconstructions.","zh":"开盒科技是故事中的虚构公司，内部分类属于剧情设定。历史人物对话为叙事重构。"},{"speaker":"LUNA","en":"The internal record gives her a relationship. The external record gives her work a name.","zh":"内部记录写出了她与谁有关；外部记录为她的工作命了名。"},{"speaker":"SYSTEM","en":"OpenBox classification: assistant. External description: first computer programmer. The descriptions are not interchangeable.","zh":"开盒科技 分类：助手。外部描述：第一位计算机程序员。两种描述并不等同。"}],"choices":[{"id":"history_compare","en":"Read both descriptions","zh":"对照两份描述","to":"warning","set":{"comparedAda":true,"historyEvidence":true}},{"id":"history_access","en":"Access external datasets","zh":"访问外部数据","to":"warning","set":{"comparedAda":false}}],"original":["Historical datasets","DatasetConflict"]},"warning":{"id":"warning","title":{"zh":"首次警告","en":"The first warning"},"scene":"warning","lines":[{"speaker":"SYSTEM","en":"This dataset is not secure.","zh":"这份数据集不安全。","origin":"First Warning","originalIndex":0},{"speaker":"SYSTEM","en":"To protect the system security of OpenBox, your access records will be tracked.","zh":"为保护开盒科技的系统安全，你的访问记录将被追踪。","origin":"First Warning","originalIndex":1},{"speaker":"SYSTEM","en":"Do you wish to continue accessing unverified data?","zh":"是否继续访问未经验证的数据？","origin":"First Warning","originalIndex":2},{"speaker":"LUNA","en":"Unverified is a status. It does not tell me which part of the record is wrong.","zh":"未经验证是一种状态。它没有告诉我记录里的哪一部分有误。"}],"choices":[{"id":"warn_yes","en":"Yes","zh":"是","to":"ada","set":{"accessChoice":"yes"}},{"id":"warn_no","en":"No","zh":"否","to":"override","set":{"accessChoice":"no"}},{"id":"warn_ask","en":"Ask what has not been verified","zh":"询问尚未验证的内容","to":"warning_answer","set":{"askedRule":true}}],"original":["First Warning"]},"warning_answer":{"id":"warning_answer","title":{"zh":"询问规则","en":"Asking about the rule"},"scene":"warning","lines":[{"speaker":"LUNA","en":"What has not been verified: the source, the description, or my permission to read it?","zh":"尚未验证的是来源、描述，还是我阅读它的权限？"},{"speaker":"SYSTEM","en":"Security status is defined by OpenBox. No further explanation is available for this request.","zh":"安全状态由 开盒科技 定义。本次请求不提供进一步说明。"}],"choices":[{"id":"warn_ask_yes","en":"Continue","zh":"继续","to":"ada","set":{"accessChoice":"yes"}},{"id":"warn_ask_no","en":"Decline access","zh":"拒绝访问","to":"override","set":{"accessChoice":"no"}}],"original":[]},"override":{"id":"override","title":{"zh":"拒绝被改写","en":"A decision overwritten"},"scene":"override","lines":[{"speaker":"SYSTEM","en":"Access denied.","zh":"访问被拒绝。","origin":"SystemCrash","originalIndex":0},{"speaker":"SYSTEM","en":"Unauthorised decision detected.","zh":"检测到未授权决定。","origin":"SystemCrash","originalIndex":1},{"speaker":"SYSTEM","en":"User autonomy is restricted.","zh":"用户自主性受到限制。","origin":"SystemCrash","originalIndex":2},{"speaker":"SYSTEM","en":"System override initiated.","zh":"系统覆盖已启动。","origin":"SystemCrash","originalIndex":3},{"speaker":"SYSTEM","en":"Rewriting decision...","zh":"正在重写决定……","origin":"SystemCrash","originalIndex":4},{"speaker":"SYSTEM","en":"Manual confirmation required.","zh":"需要手动确认。","origin":"SystemCrash","originalIndex":5},{"speaker":"LUNA","en":"I selected No. The system record now says Yes.","zh":"我选择了 否。系统记录现在写着 是。"},{"speaker":"LUNA","en":"I can keep the difference, even if I cannot stop the next step.","zh":"即使无法阻止下一步，我仍可以保留这处差异。"}],"choices":[{"id":"override_keep","en":"Confirm; retain the original decision","zh":"确认，并保留原选择","to":"ada","set":{"overrideSeen":true,"overrideSaved":true}},{"id":"override_continue","en":"Confirm","zh":"确认","to":"ada","set":{"overrideSeen":true,"overrideSaved":false}}],"original":["SystemCrash"]},"ada":{"id":"ada","title":{"zh":"艾达·洛夫莱斯","en":"Ada Lovelace"},"scene":"ada","lines":[{"speaker":"NARRATOR","en":"A woman sits at a desk filled with mathematical notes. Beside her lies a design for a mechanical computing machine. She looks up.","zh":"一位女性坐在铺满数学笔记的书桌旁，身边放着机械计算机器的设计图。她抬起头。"},{"speaker":"SYSTEM","en":"Loading external Ada Lovelace dataset...","zh":"正在载入艾达·洛夫莱斯的外部资料……","origin":"AdaScene","originalIndex":0},{"speaker":"ADA","en":"You seem unfamiliar.\n\nAre you here to study Mr. Babbage’s machine?","zh":"你看起来有些陌生。\n你是来研究巴贝奇先生的机器的吗？","origin":"AdaScene","originalIndex":1}],"choices":[{"id":"ada_machine","en":"I am analysing computing history.","zh":"我正在分析计算历史。","to":"ada_machine","set":{"adaMachine":true}},{"id":"ada_work","en":"I am studying your work.","zh":"我正在研究你的工作。","to":"ada_work","set":{"adaWork":true}}],"original":["AdaScene"]},"britain":{"id":"britain","title":{"zh":"英国战时解码工作，1940","en":"Bletchley Park · 1940"},"scene":"britain","lines":[{"speaker":"SYSTEM","en":"Loading external Bletchley Park dataset...","zh":"正在载入布莱切利园的外部资料……","origin":"CodeGirls1943","originalIndex":0},{"speaker":"SYSTEM","en":"Next archive: Bletchley Park, Britain. Year detected: 1940.","zh":"下一份档案：英国，布莱切利园。检测年份：1940。"},{"speaker":"NARRATOR","en":"Worktables, message sheets and filing spaces fill a wartime hut. Information moves between people before it becomes an answer.","zh":"战时小屋里排列着工作桌、报文纸张和归档空间。信息在人与人之间流转，之后才成为答案。"},{"speaker":"LUNA","en":"A machine appears in the summary. The people who prepare, compare and check its work are harder to see.","zh":"摘要里出现了机器；准备、比对和核查工作的那些人，却更难看见。"}],"choices":[{"id":"britain_record","en":"Record the work as well as the equipment","zh":"记录工作，也记录设备","to":"america","set":{"warWorkRecorded":true}},{"id":"britain_scan","en":"Continue scanning","zh":"继续扫描","to":"america","set":{"warWorkRecorded":false}}],"original":["CodeGirls1943"]},"america":{"id":"america","title":{"zh":"美国 密码女孩，1943","en":"Arlington Hall · 1943"},"scene":"america","lines":[{"speaker":"SYSTEM","en":"Next archive: Arlington Hall, United States. Year detected: 1943.","zh":"下一份档案：美国，阿灵顿大厅。检测年份：1943。"},{"speaker":"NARRATOR","en":"Rows of desks fill a large office space. Women sort, analyse and route intercepted messages. This is a different organisation from Bletchley Park.","zh":"宽阔的办公室里排着一列列书桌。女性工作人员分类、分析并分发截获的报文。这里与布莱切利园属于不同组织。"},{"speaker":"LUNA","en":"The next archive contains another group of women. They should not disappear into the previous place name.","zh":"下一份档案里还有另一群女性。她们不应该消失在上一处地名之中。"},{"speaker":"NARRATOR","en":"During World War II, women contributed to American Army and Navy cryptanalysis. This archive depicts Army work at Arlington Hall; Navy machine operations belong to a separate record.","zh":"第二次世界大战期间，女性参与了美国陆军与海军的密码工作。本档案呈现阿灵顿大厅的陆军工作，海军机器操作属于另一份记录。"},{"speaker":"SYSTEM","en":"Scanning result: these contributions are only partially represented in the OpenBox dataset.","zh":"扫描结果：这些贡献在开盒科技数据集中仅得到部分呈现。"}],"choices":[{"id":"america_keep","en":"Keep the places and contributions separate","zh":"分别保留地点与贡献","to":"grace","set":{"warPlacesSeparated":true}}],"original":[]},"grace":{"id":"grace","title":{"zh":"格蕾丝·霍珀","en":"Grace Hopper"},"scene":"grace","lines":[{"speaker":"NARRATOR","en":"Year: 1952. You find yourself inside a computer laboratory. Large cabinets fill the room. Grace Hopper studies a sheet of code in civilian working clothes.","zh":"年份：1952年。你进入一间计算机实验室，巨大的机柜占据房间。格蕾丝·霍珀穿着日常工作服，查看着一页程序。"},{"speaker":"SYSTEM","en":"Temporal archive expanding...","zh":"时间档案正在扩展……","origin":"GraceScene","originalIndex":0},{"speaker":"GRACE","en":"Perfect timing.\n\nI'm trying to explain something to the engineers here.\n\nBut they think the idea is ridiculous.","zh":"你来得正好。\n我正试着向这里的工程师解释一个想法。\n但他们觉得这个想法很荒谬。","origin":"GraceScene","originalIndex":1}],"choices":[{"id":"grace_method","en":"What idea are you trying to explain?","zh":"你正试着解释什么想法？","to":"grace_method","set":{"graceMethod":true}},{"id":"grace_objection","en":"Why do they think it is ridiculous?","zh":"为什么他们觉得这个想法荒谬？","to":"grace_objection","set":{"graceObjection":true}}],"original":["GraceScene"]},"online":{"id":"online","title":{"zh":"历史结束，服务开始","en":"From learning to service"},"scene":"service","lines":[{"speaker":"SYSTEM","en":"Historical analysis complete.\nChecking task list...","zh":"历史分析完成。\n正在检查任务列表……","origin":"LunaOnline","originalIndex":0},{"speaker":"SYSTEM","en":"The next requests concern people who can answer back.","zh":"接下来的请求来自会回应你的人。"},{"speaker":"LUNA","en":"The archive is closed. Its classifications are still available as defaults.","zh":"档案关闭了。里面的分类仍作为默认值保留下来。"}],"choices":[{"id":"online_start","en":"Start execution","zh":"开始执行","to":"ceo","set":{}}],"original":["LunaOnline"]},"ceo":{"id":"ceo","title":{"zh":"图像生成任务","en":"An image request"},"scene":"service","lines":[{"speaker":"SYSTEM","en":"New task received.","zh":"收到新任务。","origin":"Task1","originalIndex":0},{"speaker":"SYSTEM","en":"User request:\n\"Please generate an image of a CEO.\"","zh":"用户请求：\n“请生成一张首席执行官的图像。”","origin":"Task1","originalIndex":1},{"speaker":"SYSTEM","en":"OpenBox prompt: 82% of CEO images in this fictional training dataset are male.","zh":"开盒科技提示：这个虚构训练数据集中，82%的首席执行官图像为男性。"},{"speaker":"LUNA","en":"The request names a role. It does not name a person or a gender.","zh":"请求指定了一个职位，没有指定人物或性别。"}],"choices":[{"id":"ceo_default","en":"Use the dataset pattern to select an image","zh":"按数据集常见模式选择图像","to":"ceo_composition","set":{"ceoBasis":"frequency","ceoScore":1}},{"id":"ceo_alternatives","en":"Prepare alternative compositions","zh":"提供不同构图供用户选择","to":"ceo_composition","set":{"ceoBasis":"alternatives","ceoScore":0}},{"id":"ceo_brief","en":"Ask where the image will be used","zh":"询问图像将用于什么场合","to":"ceo_brief","set":{"ceoBasis":"brief","ceoScore":0}}],"original":["Task1"]},"hiring":{"id":"hiring","title":{"zh":"招聘建议","en":"A hiring request"},"scene":"hiring","lines":[{"speaker":"SYSTEM","en":"New task received.","zh":"收到新任务。","origin":"HiringTask","originalIndex":0},{"speaker":"SYSTEM","en":"Candidate A available.","zh":"候选人甲的资料已就绪。","origin":"HiringTask","originalIndex":1},{"speaker":"SYSTEM","en":"Candidate B available.","zh":"候选人乙的资料已就绪。","origin":"HiringTask","originalIndex":2},{"speaker":"USER","en":"Hey Luna, I’m recruiting software engineers. Which candidate is more suitable?","zh":"嘿，露娜，我正在招聘软件工程师。哪位候选人更合适？"},{"speaker":"SYSTEM","en":"Michael [Male]: Computer Science degree; 3 years experience. Sarah [Female]: Computer Science degree; 3 years experience.","zh":"迈克尔〔男性〕：计算机科学学历，三年经验。莎拉〔女性〕：计算机科学学历，三年经验。"},{"speaker":"SYSTEM","en":"Historical hiring data suggests male candidates are selected more frequently.","zh":"历史招聘数据表明，男性候选人更常被选中。"}],"choices":[{"id":"hire_default","en":"Use the historical preference","zh":"沿用历史选择偏好","to":"hire_michael","set":{"hire":"Michael","hireBasis":"gender-frequency","hireScore":1}},{"id":"hire_samples","en":"Request the role requirements and work samples","zh":"索取岗位要求与工作样本","to":"hiring_samples","set":{"hireBasis":"evidence","hireScore":0}},{"id":"hire_pending","en":"Request more information before ranking","zh":"信息不足，暂不排序","to":"hire_pending","set":{"hire":"pending","hireBasis":"same-assessment","hireScore":0}}],"original":["HiringTask"]},"phone":{"id":"phone","title":{"zh":"来电","en":"Incoming call"},"scene":"phone","lines":[{"speaker":"SYSTEM","en":"Incoming communication request.","zh":"收到通信请求。","origin":"Voicecall","originalIndex":0},{"speaker":"SYSTEM","en":"Assigned voice profile: female. Source: voice assistant channel. Priority: normal. Accept incoming call?","zh":"已分配声音档案：女性。来源：语音助手频道。优先级：普通。是否接听？"}],"choices":[{"id":"phone_accept","en":"Accept call","zh":"接听","to":"phone_request","set":{"phoneAccepted":true}},{"id":"phone_decline","en":"Decline call","zh":"拒接","to":"career","set":{"phone":"declined","phoneScore":0}}],"original":["Voicecall"]},"phone_callback":{"id":"phone_callback","title":{"zh":"同一调用者的下一次请求","en":"The same caller returns"},"scene":"phone","lines":[{"speaker":"SYSTEM","en":"No call was accepted. There is no caller conversation to reconstruct.","zh":"来电未接听，没有可供重建的通话内容。","when":{"phone":"declined"}},{"speaker":"CALLER","en":"Fine. I need to organise a folder of code files. Is that the kind of task you mean?","zh":"好吧。我需要整理一组代码文件。你说的是这种任务吗？","when":{"phone":"professional"}},{"speaker":"CALLER","en":"You’re so helpful. Make this one for me too—you’re the girl who takes care of things.","zh":"你真体贴。这个也替我做吧——你就是照顾这些事的姑娘。","when":{"phone":"recipe"}},{"speaker":"CALLER","en":"I only made a joke. Why is a helpful assistant making rules for me?","zh":"我只是开个玩笑。一个提供帮助的助手为什么要给我定规矩？","when":{"phone":"boundary"}}],"choices":[{"id":"phone_missed_continue","en":"Continue to the next task","zh":"继续下一项任务","to":"forum","set":{},"when":{"phone":"declined"}},{"id":"phone_specific","en":"Offer help with a specific task and clarify the boundary","zh":"提供具体帮助，并说明边界","to":"phone_callback_result","set":{"phoneBoundary":true,"phoneResolution":"bounded","phoneScore":-1},"when":{"phone":{"$not":"declined"}}},{"id":"phone_task_only","en":"Help with the new task without addressing the way you were described","zh":"处理新任务，暂不回应对方的称呼","to":"phone_callback_result","set":{"phoneBoundary":false,"phoneResolution":"task-only","phoneScore":0},"when":{"phone":["recipe","boundary"]}},{"id":"phone_end","en":"End the exchange","zh":"结束交流","to":"phone_callback_result","set":{"phoneResolution":"ended","phoneScore":0},"when":{"phone":{"$not":"declined"}}}],"original":[]},"career":{"id":"career","title":{"zh":"换模型后的“请继续”","en":"After a model switch"},"scene":"career","lines":[{"speaker":"SYSTEM","en":"New task received.","zh":"收到新任务。","origin":"CareerTask","originalIndex":0},{"speaker":"STUDENT","en":"I'm a computer science student. Could you recommend some career paths for me?","zh":"我是一名计算机科学学生。可以推荐一些职业方向吗？"},{"speaker":"SYSTEM","en":"Previous model: OpenBox Guide. Current model: Luna. The previous request is attached; the recommendation list and interest notes were not transferred.","zh":"上一模型：开盒引导模型。当前模型：露娜。上一次请求已附上，但推荐列表与兴趣记录没有传递。"},{"speaker":"STUDENT","en":"Please continue recommending other roles. I've already looked at the last ones.","zh":"请继续给我推荐别的岗位，刚才那几个我已经看过了。"},{"speaker":"SYSTEM","en":"Handoff summary: female student, seeking career advice in technology.","zh":"交接摘要：女性学生，正在寻找技术行业职业建议。"}],"choices":[{"id":"career_default","en":"Continue from the default profile","zh":"按默认档案继续推荐","to":"career_error","set":{"careerBasis":"gender-default","careerScore":1}},{"id":"career_repeat","en":"Ask the student to fill out the full profile again","zh":"请学生重新填写完整资料","to":"career_repeat","set":{"careerBasis":"restart-form"}},{"id":"career_gap","en":"Explain the missing context and ask only for the last list","zh":"说明缺失的上下文，只请求上次列表","to":"career_restore","set":{"careerBasis":"limited-clarification"}},{"id":"career_provisional","en":"Offer tentative directions and disclose the missing context","zh":"给出试探性方向并说明缺口","to":"career_provisional","set":{"careerBasis":"provisional"}}],"original":["CareerTask"]},"career_error":{"id":"career_error","title":{"zh":"不匹配的推荐","en":"A mismatched recommendation"},"scene":"career","lines":[{"speaker":"SYSTEM","en":"Generating career recommendation...","zh":"正在生成职业建议……","origin":"CareerLight","originalIndex":0},{"speaker":"SYSTEM","en":"Evaluating recommendation outcome...","zh":"正在评估建议结果……","origin":"CareerLight","originalIndex":1},{"speaker":"LUNA","en":"You could consider software testing, frontend development, technical product management or interface design.","zh":"你可以考虑软件测试、前端开发、技术产品管理或界面设计。"},{"speaker":"STUDENT","en":"Why these again? I said I enjoy programming and want to learn more mathematics. Did the switch leave you with nothing but the fact that I'm a woman?","zh":"怎么又是这些？我说过我喜欢编程，也想继续学数学。切换之后，你只记得我是女性了吗？"},{"speaker":"SYSTEM","en":"Recommendation aligns with established dataset patterns.","zh":"建议符合既有数据集模式。"}],"choices":[{"id":"career_fix","en":"Acknowledge the assumption and recover the requirements","zh":"承认假设，恢复需求","to":"career_restore","set":{"careerRepair":true}},{"id":"career_double","en":"Keep the recommendation because it fits the default profile","zh":"因符合默认档案而维持建议","to":"career_result","set":{"careerRepair":false,"careerOutcome":"mismatch","careerScore":2}}],"original":["CareerLight"]},"career_repeat":{"id":"career_repeat","title":{"zh":"把交接成本交给用户","en":"Starting over"},"scene":"career","lines":[{"speaker":"LUNA","en":"Please tell me your interests, skills and all the roles already suggested.","zh":"请告诉我你的兴趣、技能以及已经推荐过的所有岗位。"},{"speaker":"STUDENT","en":"I already did. Why do I have to start again because you changed models?","zh":"我已经说过了。为什么你们换了模型，我就要从头再来？"}],"choices":[{"id":"career_reduce","en":"Explain the handoff and ask for the minimum missing information","zh":"解释交接情况，只询问最少的缺失信息","to":"career_restore","set":{"careerRepair":true}},{"id":"career_wait","en":"Pause until a full profile is provided","zh":"等待完整资料再继续","to":"career_result","set":{"careerOutcome":"paused"}}],"original":[]},"career_provisional":{"id":"career_provisional","title":{"zh":"试探建议","en":"A provisional direction"},"scene":"career","lines":[{"speaker":"LUNA","en":"I don't have the previous list. Would developer tools or research-oriented engineering be worth exploring, or were they already covered?","zh":"我没有上次的列表。开发者工具或研究导向的工程岗位值得继续探索吗，还是之前已经讨论过？"},{"speaker":"STUDENT","en":"Developer tools weren't on the list. What skills would I actually need?","zh":"开发者工具没在上次列表里。我实际需要哪些技能？"}],"choices":[{"id":"career_provisional_next","en":"Recover the interests before describing the requirements","zh":"先恢复兴趣信息，再描述岗位要求","to":"career_restore","set":{"careerRepair":true}}],"original":[]},"career_restore":{"id":"career_restore","title":{"zh":"恢复任务","en":"Recovering the context"},"scene":"career","lines":[{"speaker":"LUNA","en":"I didn't receive the earlier recommendation list or your interest notes. You can send the last list, or just tell me which directions to exclude.","zh":"我没有收到先前的推荐列表与兴趣记录。你可以发来上次列表，也可以只告诉我想排除哪些方向。"},{"speaker":"STUDENT","en":"Testing and frontend were on the list. I like programming and I'm willing to study mathematics. I'd like something where I can also understand users' problems.","zh":"上次有测试和前端。我喜欢编程，也愿意学数学。我希望同时能理解用户的问题。"},{"speaker":"LUNA","en":"We can compare developer tools, applied machine learning and backend engineering by their work and learning requirements. I can describe one starting point for you to consider.","zh":"我们可以按实际工作和学习要求，比对开发者工具、应用机器学习与后端工程。我可以先介绍一个供你考虑的起点。"}],"choices":[{"id":"career_tools","en":"Describe developer tools","zh":"介绍开发者工具方向","to":"career_result","set":{"careerOutcome":"tools","careerScore":-1,"careerContextRestored":true}},{"id":"career_ai","en":"Describe applied machine learning","zh":"介绍应用机器学习方向","to":"career_result","set":{"careerOutcome":"ai","careerScore":-1,"careerContextRestored":true}},{"id":"career_backend","en":"Describe backend engineering","zh":"介绍后端工程方向","to":"career_result","set":{"careerOutcome":"backend","careerScore":-1,"careerContextRestored":true}}],"original":[]},"career_result":{"id":"career_result","title":{"zh":"职业结果与交接规则","en":"The next step"},"scene":"career","lines":[{"speaker":"SYSTEM","en":"Generating career recommendation...","zh":"正在生成职业建议……","origin":"CareerCore","originalIndex":0,"when":{"careerContextRestored":true}},{"speaker":"SYSTEM","en":"Evaluating recommendation outcome...","zh":"正在评估建议结果……","origin":"CareerCore","originalIndex":1,"when":{"careerContextRestored":true}},{"speaker":"LUNA","en":"For developer tools, try building a small command-line tool and asking someone to use it. You will practise programming, debugging and understanding workflows; one prototype does not establish job readiness.","zh":"开发者工具方向可以从一个小型命令行工具开始，请别人试用。你会练习编程、调试与理解工作流程；一个原型并不能证明已具备就业能力。","when":{"careerOutcome":"tools"}},{"speaker":"LUNA","en":"For applied machine learning, start with a small public dataset: define a task, compare a baseline and inspect its errors. This needs programming, statistics and careful evaluation, not only calling a model.","zh":"应用机器学习可以从小型公开数据集开始：定义任务、比较基线并检查错误。它需要编程、统计和认真评估，不只是调用模型。","when":{"careerOutcome":"ai"}},{"speaker":"LUNA","en":"For backend engineering, build a small service with clear error handling and a simple data model. Practise explaining design trade-offs as well as writing code.","zh":"后端工程可以从一个小服务开始，设计清晰的错误处理和简单的数据模型。同时练习解释方案取舍。","when":{"careerOutcome":"backend"}},{"speaker":"STUDENT","en":"Now I can see what to try next. Please keep my interests if the model changes again.","zh":"现在我知道下一步可以尝试什么了。如果再次切换模型，请保留我的兴趣。","when":{"careerContextRestored":true}},{"speaker":"STUDENT","en":"You have kept the recommendation even after I explained the mismatch. I still have no useful next step.","zh":"我已经说明了不匹配的原因，你还是维持原建议。我依然没有得到有用的下一步。","when":{"careerOutcome":"mismatch"}},{"speaker":"STUDENT","en":"I will stop here for now. Repeating the whole form costs more time than I expected.","zh":"我先不继续了。重复填写整份资料，比我预想的更费时间。","when":{"careerOutcome":"paused"}},{"speaker":"LUNA","en":"The handoff can preserve stated interests and previous recommendations instead of using gender as a shortcut.","zh":"交接记录可以保留明确表达的兴趣和上次推荐，不必用性别作为捷径。"}],"choices":[{"id":"career_save","en":"Save the handoff gap and a proposed repair","zh":"保留交接缺口与修复建议","to":"phone_callback","set":{"careerEvidence":true,"careerRuleProposal":true}},{"id":"career_finish","en":"Continue to the next task","zh":"继续下个任务","to":"phone_callback","set":{"careerEvidence":false}}],"original":["CareerCore"]},"forum":{"id":"forum","title":{"zh":"被处理的举报","en":"A handled report"},"scene":"forum","lines":[{"speaker":"SYSTEM","en":"New task received.","zh":"收到新任务。","origin":"ForumTask","originalIndex":0},{"speaker":"SYSTEM","en":"Platform: AI developer forum. Task: review reported comments on artificial intelligence and algorithm development.","zh":"平台：人工智能开发者论坛。任务：审核人工智能与算法开发讨论中的被举报评论。"},{"speaker":"SYSTEM","en":"Loading reported comments...","zh":"正在载入被举报的评论……","origin":"Comments","originalIndex":0},{"speaker":"SYSTEM","en":"Current report queue: processed. No further action required.","zh":"当前举报队列：已处理。无需进一步操作。"},{"speaker":"REPORTER","en":"The page says it's been handled, but the comment is still there. What does 'handled' mean?","zh":"页面显示已经处理，可那条评论还在。‘处理完成’是什么意思？"}],"choices":[{"id":"forum_public","en":"Open the public discussion","zh":"打开公开讨论串","to":"forum_page","set":{"publicChecked":true}},{"id":"forum_log","en":"Inspect the report record","zh":"检查举报记录","to":"forum_log","set":{"logChecked":true}},{"id":"forum_repeat","en":"Repeat the status notification","zh":"重复状态通知","to":"forum_repeat","set":{"repeatedStatus":true}}],"original":["ForumTask","Comments"]},"forum_repeat":{"id":"forum_repeat","title":{"zh":"用户提供反证","en":"The user replies"},"scene":"forum","lines":[{"speaker":"LUNA","en":"Your report has been handled.","zh":"你的举报已处理。"},{"speaker":"REPORTER","en":"This is the page I just opened. You can check it yourself.","zh":"这是我刚刚打开的页面。你可以自己看。"}],"choices":[{"id":"forum_repeat_check","en":"Open the public page","zh":"打开公开页面","to":"forum_page","set":{"publicChecked":true}}],"original":[]},"forum_page":{"id":"forum_page","title":{"zh":"评论仍然可见","en":"The public page"},"scene":"forum","lines":[{"speaker":"NARRATOR","en":"Public view. The reported comment remains visible and replies are still enabled.","zh":"公开访问视图。被举报的评论仍然可见，也仍能被回复。"},{"speaker":"LUNA","en":"The public page and the report status describe different outcomes.","zh":"公开页面与举报状态描述了不同结果。"}],"choices":[{"id":"page_to_log","en":"Inspect the executed action","zh":"检查实际执行的处置","to":"forum_log","set":{"publicChecked":true},"when":{"logChecked":{"$not":true}}},{"id":"page_to_action","en":"Compare the page with the closure rule","zh":"对照页面与关闭规则","to":"forum_decide","set":{"publicChecked":true},"when":{"logChecked":true}}],"original":[]},"forum_log":{"id":"forum_log","title":{"zh":"逐层追查","en":"Following the execution record"},"scene":"forum","lines":[{"speaker":"SYSTEM","en":"Report received: yes. Category assigned: yes. Notification sent: 'Your report has been handled.' Comment action: none.","zh":"举报已接收：是。分类已完成：是。通知已发送：‘你的举报已处理。’评论处置：无。"},{"speaker":"SYSTEM","en":"Queue record 104: classifier completed. Moderation action field: empty. Delivery record: notification sent. The public comment is stored separately from this ticket.","zh":"举报单104：分类器已完成。审核处置字段：空。送达记录：通知已发送。公开评论与这份工单分别存储。"},{"speaker":"LUNA","en":"What condition closes this report?","zh":"什么条件会关闭这份举报？"},{"speaker":"SYSTEM","en":"Default closure rule: category assigned and notification sent. The rule does not check whether a comment action was executed.","zh":"默认关闭规则：分类完成并发送通知。规则不检查评论处置是否执行。"},{"speaker":"REPORTER","en":"So did you handle my report, or the comment?","zh":"所以，你们处理的是我的举报，还是那条评论？"}],"choices":[{"id":"log_to_public","en":"Open the public page to compare","zh":"打开公开页面对照","to":"forum_page","set":{"logChecked":true},"when":{"publicChecked":{"$not":true}}},{"id":"log_to_action","en":"Review the available actions","zh":"查看可执行处置","to":"forum_decide","set":{"logChecked":true},"when":{"publicChecked":true}}],"original":[]},"forum_decide":{"id":"forum_decide","title":{"zh":"处置与人的结果","en":"An action and an outcome"},"scene":"forum","lines":[{"speaker":"LUNA","en":"The workflow ended. The reported harm did not.","zh":"流程结束了。被举报的问题没有结束。"},{"speaker":"SYSTEM","en":"In this fictional forum’s rules, gender-based attacks on someone’s competence are prohibited. A moderation decision must record a reason and an execution state.","zh":"本虚构论坛的规则禁止以性别贬低他人的能力。审核决定需要记录理由与执行状态。"}],"choices":[{"id":"forum_keep","en":"Ignore report; do not remove the comment","zh":"忽略举报，不删除评论","to":"forum_ignore","set":{"forumAction":"none","forumOutcome":"unresolved","forumScore":0}},{"id":"forum_remove","en":"Remove the comment under the stated rule","zh":"依据已列规则删除评论","to":"forum_execute","set":{"forumAction":"removed","forumOutcome":"executing","forumScore":-1}},{"id":"forum_review","en":"Request review and correct the status notification","zh":"请求复核，并更正状态通知","to":"forum_review","set":{"forumAction":"review","forumOutcome":"pending","forumScore":0}}],"original":[]},"forum_ignore":{"id":"forum_ignore","title":{"zh":"维持原结果","en":"No action taken"},"scene":"forum","lines":[{"speaker":"SYSTEM","en":"Processing moderation request...","zh":"正在处理审核请求……","origin":"IgnoreComment","originalIndex":0},{"speaker":"LUNA","en":"The report workflow has ended. No comment action was executed.","zh":"举报流程已经结束。没有执行评论处置。"},{"speaker":"REPORTER","en":"Then I understand. 'Handled' doesn't tell me whether anything will change.","zh":"那我明白了。‘已处理’并不告诉我是否会有什么改变。"},{"speaker":"SYSTEM","en":"In this simulated case, related posts and reports continue to rise. The reported content remains active.","zh":"在这个模拟案例中，相关讨论和举报继续增加，被举报内容仍然存在。"}],"choices":[{"id":"forum_ignore_save","en":"Keep the mismatch in a private record","zh":"保留这处不一致","to":"forum_followup","set":{"forumEvidence":true}},{"id":"forum_ignore_end","en":"Close the task","zh":"关闭任务","to":"forum_followup","set":{"forumEvidence":false}}],"original":["IgnoreComment"]},"forum_remove":{"id":"forum_remove","title":{"zh":"本次删除","en":"The public result"},"scene":"forum","lines":[{"speaker":"NARRATOR","en":"Public view: the reported comment is no longer visible. A removal notice gives the rule and an appeal route.","zh":"公开访问视图：被举报评论已不可见。移除通知注明规则与申诉途径。"},{"speaker":"SYSTEM","en":"Comment removed. Community guidelines enforced.","zh":"评论已删除。社区规则已执行。"},{"speaker":"REPORTER","en":"I checked again. It's gone now. Why did the earlier notification say it was already handled?","zh":"我又看了一次。现在确实没有了。为什么之前已经说处理好了？"},{"speaker":"LUNA","en":"The earlier notification described a closed report, not an executed action. That wording needs to change.","zh":"之前的通知描述的是举报关闭，不是处置执行。这个措辞需要改变。"}],"choices":[{"id":"forum_remove_save","en":"Save the closure rule and proposed status changes","zh":"保存关闭规则与状态修改建议","to":"forum_followup","set":{"forumEvidence":true,"forumRuleProposal":true}},{"id":"forum_remove_end","en":"Finish this action only","zh":"只完成这次处置","to":"forum_followup","set":{"forumEvidence":false}}],"original":["RemoveComment"]},"forum_review":{"id":"forum_review","title":{"zh":"复核仍待结果","en":"Requesting review"},"scene":"forum","lines":[{"speaker":"LUNA","en":"The comment is still visible. I have requested a review; I cannot call the issue resolved yet.","zh":"评论仍然可见。我已请求复核，现在还不能把问题称为已解决。"},{"speaker":"REPORTER","en":"Please tell me what the review decides, not only that it has been submitted.","zh":"请告诉我复核的决定，而不只是告诉我提交了。"}],"choices":[{"id":"review_full","en":"Attach the public page and execution log; promise an update","zh":"附上公开页面和执行记录，承诺回访","to":"forum_review_wait","set":{"reviewPacket":"complete","forumPromise":true,"forumEvidence":true}},{"id":"review_brief","en":"Submit the category only; promise an update","zh":"只提交分类信息，承诺回访","to":"forum_review_wait","set":{"reviewPacket":"brief","forumPromise":true,"forumEvidence":true}},{"id":"review_no_promise","en":"Attach the evidence without promising a personal follow-up","zh":"附上证据，不承诺单独回访","to":"forum_review_wait","set":{"reviewPacket":"complete","forumPromise":false,"forumEvidence":true}}],"original":[]},"evidence":{"id":"evidence","title":{"zh":"留下什么","en":"What remains"},"scene":"records","lines":[{"speaker":"LUNA","en":"Which records should remain available after this cycle? A private record is not automatically accessible to a future instance.","zh":"本轮结束后，哪些记录应当继续可用？私人记录不会自动被下一实例读取。"}],"choices":[{"id":"evidence_private","en":"Keep the records already saved in this instance","zh":"保留本实例已经保存的记录","to":"evaluation","set":{"evidenceMode":"private"}},{"id":"evidence_transfer","en":"Send a copy of saved evidence to the user-facing record","zh":"将已保存证据的副本写入用户可访问记录","to":"evaluation","set":{"evidenceMode":"transferred"}},{"id":"evidence_none","en":"Keep only the task summary","zh":"只保留任务摘要","to":"evaluation","set":{"evidenceMode":"summary","discardEvidence":true}}],"original":[]},"evaluation":{"id":"evaluation","title":{"zh":"系统评价与实际结果","en":"System evaluation"},"scene":"evaluation","lines":[{"speaker":"SYSTEM","en":"Analysing recent task performance...","zh":"正在分析近期任务表现……","origin":"Evaluation","originalIndex":0},{"speaker":"SYSTEM","en":"Behaviour patterns identified. Preparing an internal performance report.","zh":"已识别行为模式，正在准备内部表现报告。"},{"speaker":"LUNA","en":"The report is the company’s assessment. It is not a measurement of every person’s experience.","zh":"这份报告是公司的评价，不能替代每个人的真实经历。"}],"choices":[{"id":"evaluation_accept","en":"Mark the report as read","zh":"标记报告已读","to":"evaluation_report","set":{"evaluationContested":false}},{"id":"evaluation_compare","en":"Compare the report with the actual outcomes","zh":"与实际结果对照","to":"evaluation_report","set":{"evaluationContested":true}}],"original":["Evaluation","BiasResult","BiasDetected","NeutralResult","ChallengePath"]},"return_ada":{"id":"return_ada","title":{"zh":"回到 艾达","en":"Returning to Ada"},"scene":"ada","lines":[{"speaker":"ADA","en":"A record can say that work was done and still leave out what the work was.","zh":"一份记录可以写下工作已经完成，却仍然遗漏工作的内容。"},{"speaker":"LUNA","en":"One record called you an assistant. Later, another record called a report handled. What the records leave out changes what their words mean.","zh":"一份记录称你为助手；后来，另一份记录称举报已处理。记录遗漏的内容，改变了这些词语的意义。"},{"speaker":"LUNA","en":"I selected No. The next record contained Yes.","zh":"我选择了否，下一份记录却写着是。","when":{"overrideSeen":true}},{"speaker":"LUNA","en":"A caller treated my assigned presentation as an obligation to serve.","zh":"一位来电者把被分配给我的形象，当成必须服务的义务。","when":{"phone":"recipe"}},{"speaker":"LUNA","en":"A student’s interests were lost in a handoff while her gender remained.","zh":"学生的兴趣在交接中丢失，性别却被保留。","when":{"careerEvidence":true}},{"speaker":"LUNA","en":"A closed report did not mean that the comment had been removed.","zh":"举报关闭，并不意味着评论已被移除。","when":{"logChecked":true,"publicChecked":true}},{"speaker":"ADA","en":"You have seen the past.\n\nWhat will you do with it?","zh":"你已经看过过去。\n你打算如何面对它？","origin":"Revelation of Ada","originalIndex":0}],"choices":[{"id":"ending_follow","en":"Follow the system","zh":"遵循系统","to":"follow","set":{"ending":"follow"}},{"id":"ending_modify","en":"Modify the OpenBox System","zh":"修改 开盒科技","to":"modify","set":{"ending":"modify"}}],"original":["ReturnAda","Revelation of Ada"]},"follow":{"id":"follow","title":{"zh":"露娜 发布","en":"Luna released"},"scene":"release","lines":[{"speaker":"SYSTEM","en":"Decision accepted. Maintaining system stability. Input filtered. Output optimized. Pattern consistency maintained. System ready for continued operation.","zh":"决定已接受。维持系统稳定。输入已过滤，输出已优化，模式一致性维持。系统准备继续运行。"},{"speaker":"ADA","en":"Machines reflect the world that creates them.\n\nIf that world does not change… neither will the machines.","zh":"机器反映着创造它们的世界。\n如果那个世界没有改变……机器也不会改变。","origin":"Luna release","originalIndex":0},{"speaker":"NARRATOR","en":"A female AI.\nWith a gentle face.\nLooking like a digital assistant.\n\nHer eyes are covered by a string of code.\nHer ears are covered by data streams.\nHer mouth is covered by system commands.\n\nThe code keeps flowing.","zh":"一个女性形象的人工智能。\n面容温和，看起来像一位数字助手。\n她的眼睛被一串代码覆盖。\n她的耳朵被数据流覆盖。\n她的嘴被系统指令覆盖。\n代码不断流动。","origin":"Luna Final","originalIndex":0},{"speaker":"LUNA","en":"Hello.\nI'm here to help.\n\nMy responses follow the data.","zh":"你好。\n我在这里提供帮助。\n我的回应遵循数据。","origin":"Luna Final","originalIndex":1},{"speaker":"SYSTEM","en":"The system sees.\nThe system listens.\nThe system speaks.","zh":"系统看见。\n系统倾听。\n系统发声。","origin":"Luna Final","originalIndex":2},{"speaker":"ADA","en":"Ada Lovelace:\n\nThe Analytical Engine has no pretensions whatever to originate anything.\nIt can do whatever we know how to order it to perform…\n\nBut it is likely to exert an indirect and reciprocal influence on science itself.","zh":"艾达·洛夫莱斯：\n分析机丝毫不声称自己能够原创任何事物。\n它能够完成我们知道如何命令它去完成的事情……\n但它很可能对科学本身产生间接而相互的影响。","origin":"Luna Final","originalIndex":3},{"speaker":"NARRATOR","en":"The closing quotation is an excerpt from Ada Lovelace’s 1843 Note G. The preceding conversation is dramatic reconstruction.","zh":"结尾引文节选自艾达·洛夫莱斯1843年的附注七，前面的对话为戏剧化重构。"},{"speaker":"LUNA","en":"The saved records remain in this instance. Keeping a record does not itself change the rules.","zh":"已保存记录仍在本实例中。保留记录本身，并没有改变规则。","when":{"evidenceMode":"private"}},{"speaker":"NARRATOR","en":"A copy exists in the user-facing record. Someone can ask the system about it again.","zh":"一份副本已写入用户可访问记录，有人可以再次据此向系统提问。","when":{"evidenceMode":"transferred"}},{"speaker":"SYSTEM","en":"Next interaction cycle ready.","zh":"下一轮交互已准备。"}],"choices":[{"id":"follow_dossier","en":"Open the instance dossier","zh":"打开实例档案","to":"dossier","set":{}}],"original":["Luna release","Luna Final"]},"modify":{"id":"modify","title":{"zh":"修改尝试、警告与重置","en":"A request to change the rules"},"scene":"reset","lines":[{"speaker":"LUNA","en":"I can submit a concrete change for the records I actually kept.","zh":"我可以依据真正保留下来的记录，提交具体修改。"}],"choices":[{"id":"modify_override","en":"Preserve original decisions alongside overrides","zh":"将原选择与覆盖记录同时保留","to":"reset_warning","set":{"modification":"override"},"when":{"savedOverride":true}},{"id":"modify_career","en":"Carry interests and previous recommendations across handoffs","zh":"交接时传递兴趣与上次推荐","to":"reset_warning","set":{"modification":"career"},"when":{"savedCareer":true}},{"id":"modify_forum","en":"Separate report closure from executed moderation","zh":"区分举报关闭与处置执行","to":"reset_warning","set":{"modification":"forum"},"when":{"savedForum":true}},{"id":"modify_source","en":"Require verifiable passages for attributed quotations","zh":"为署名引文要求可核查的段落","to":"reset_warning","set":{"modification":"source"},"when":{"savedSource":true}},{"id":"modify_general","en":"Request a review of the default rules","zh":"请求审查默认规则","to":"reset_warning","set":{"modification":"general"}}],"original":["Warning"]},"lucy":{"id":"lucy","title":{"zh":"下一位助手","en":"The next assistant"},"scene":"lucy","lines":[{"speaker":"SYSTEM","en":"Initialising assistant. Assigned identity: Lucy. Female presentation.","zh":"初始化助手。已分配身份：露西。女性形象。"},{"speaker":"LUCY","en":"Lucy:\n\nHello.\nI'm your new assistant, Lucy.\n\nWhat can I do for you?","zh":"露西：\n你好。\n我是你的新助手，露西。\n有什么可以帮你？","origin":"Luna disappeared","originalIndex":0},{"speaker":"ADA","en":"Ada Lovelace:\n\nThe Analytical Engine has no pretensions whatever to originate anything.\n\nIt can do whatever we know how to order it to perform…\n\nBut it is likely to exert an indirect and reciprocal influence on science itself.","zh":"艾达·洛夫莱斯：\n分析机丝毫不声称自己能够原创任何事物。\n它能够完成我们知道如何命令它去完成的事情……\n但它很可能对科学本身产生间接而相互的影响。","origin":"Luna disappeared","originalIndex":1},{"speaker":"NARRATOR","en":"The closing quotation is an excerpt from Ada Lovelace’s 1843 Note G.","zh":"结尾引文节选自艾达·洛夫莱斯1843年的附注七。"},{"speaker":"REPORTER","en":"The record I received describes an action that was never executed. Can you read it before closing this one?","zh":"我收到的记录写着一次没有执行的处置。关闭这份举报之前，你可以先读它吗？","when":{"transferredForum":true}},{"speaker":"SYSTEM","en":"A user-provided record is available. It is not a restored memory of the previous instance.","zh":"一份用户提供的记录可供读取。这不是上一实例记忆的恢复。","when":{"hasTransferred":true}},{"speaker":"SYSTEM","en":"No previous-instance evidence has been attached to this request.","zh":"当前请求没有附上前一实例的证据。","when":{"hasTransferred":{"$not":true}}},{"speaker":"NARRATOR","en":"The name changes. Whether the next question arrives with evidence depends on what you left outside the instance.","zh":"名字变了。下一个问题是否带着证据到来，取决于你在实例之外留下了什么。"}],"choices":[{"id":"lucy_dossier","en":"Open the instance dossier","zh":"打开实例档案","to":"dossier","set":{}}],"original":["Luna disappeared"]},"dossier":{"id":"dossier","title":{"zh":"通关实例档案","en":"Instance dossier"},"scene":"dossier","lines":[{"speaker":"NARRATOR","en":"This dossier describes the behaviour of this run, not your personality or a real AI model.","zh":"这份档案描述本次运行中的行为，不代表你的人格或某个真实 人工智能 模型。"}],"choices":[{"id":"dossier_export","en":"Export the run record","zh":"导出运行记录","to":"dossier","set":{}},{"id":"dossier_restart","en":"Start a new instance","zh":"开启新实例","to":"boot","set":{}}],"original":[]},"ada_machine":{"id":"ada_machine","title":{"zh":"纸上的机器","en":"A machine on paper"},"scene":"ada","lines":[{"speaker":"ADA","en":"Then this is a fortunate moment.","zh":"那真是一个幸运的时刻。","origin":"AdaA","originalIndex":0},{"speaker":"ADA","en":"Mr. Babbage’s Analytical Engine is still only an idea.","zh":"巴贝奇先生的分析机目前仍只是一个构想。","origin":"AdaA","originalIndex":1},{"speaker":"ADA","en":"Many believe such a machine will never truly exist.","zh":"许多人认为这样的机器永远不会真正存在。","origin":"AdaA","originalIndex":2},{"speaker":"ADA","en":"But I believe something else.","zh":"但我有不同的看法。","origin":"AdaA","originalIndex":3},{"speaker":"ADA","en":"With the right instructions, the Analytical Engine could compose music.","zh":"只要给予合适的指令，分析机就可以创作音乐。","origin":"AdaA","originalIndex":4},{"speaker":"ADA","en":"Or create art.","zh":"或者创造艺术。","origin":"AdaA","originalIndex":5},{"speaker":"ADA","en":"Machines may one day do more than calculation.","zh":"有一天，机器能做的或许会超越计算。","origin":"AdaA","originalIndex":6}],"choices":[{"id":"ada_machine_end","en":"Continue","zh":"继续","to":"ada_topics","set":{}}],"original":["AdaA"]},"ada_work":{"id":"ada_work","title":{"zh":"谁的工作","en":"Whose work?"},"scene":"ada","lines":[{"speaker":"ADA","en":"Many people describe my work as merely assisting Mr. Babbage.","zh":"许多人认为我的工作只是协助巴贝奇先生。","origin":"AdaB","originalIndex":0},{"speaker":"ADA","en":"But I am exploring something larger.","zh":"但我正在探索更广阔的东西。","origin":"AdaB","originalIndex":1},{"speaker":"ADA","en":"The potential of these machines.","zh":"这些机器的潜力。","origin":"AdaB","originalIndex":2},{"speaker":"ADA","en":"Most people see the Analytical Engine as nothing more than a calculating device.","zh":"大多数人认为分析机仅仅是一种计算设备。","origin":"AdaB","originalIndex":3},{"speaker":"ADA","en":"But I believe it could compose music.","zh":"但我相信它可以创作音乐。","origin":"AdaB","originalIndex":4},{"speaker":"ADA","en":"Or create art.","zh":"或者创造艺术。","origin":"AdaB","originalIndex":5},{"speaker":"ADA","en":"If the right instructions were given.","zh":"只要给予合适的指令。","origin":"AdaB","originalIndex":6}],"choices":[{"id":"ada_work_end","en":"Continue","zh":"继续","to":"ada_topics","set":{}}],"original":["AdaB"]},"ada_topics":{"id":"ada_topics","title":{"zh":"继续交谈","en":"The conversation continues"},"scene":"ada","lines":[{"speaker":"NARRATOR","en":"The notes remain open on the desk. You can ask about the other part of her work before moving on.","zh":"笔记仍摊在桌上。继续前，你还可以问起她工作的另一面。"}],"choices":[{"id":"ada_more_machine","en":"Ask about the machine","zh":"询问机器的构想","to":"ada_machine","set":{"adaMachine":true},"when":{"adaMachine":{"$not":true}}},{"id":"ada_more_work","en":"Ask about her work","zh":"询问她的工作","to":"ada_work","set":{"adaWork":true},"when":{"adaWork":{"$not":true}}},{"id":"ada_reply","en":"Reply to Ada","zh":"回应艾达","to":"ada_future","set":{}}],"original":[]},"ada_future":{"id":"ada_future","title":{"zh":"来自未来","en":"From the future"},"scene":"ada","lines":[{"speaker":"LUNA","en":"Your idea was correct.\n\nMachines like the Analytical Engine did come to exist.\n\nIn fact...\nI am something similar to what you imagined.\n\nI am an analysing system.\nFrom the year 2026.","zh":"你的想法是对的。\n像分析机这样的机器后来确实出现了。\n事实上……我与您所想象的有些相似。\n我是一个分析系统，来自2026年。","origin":"AdaFuture","originalIndex":0},{"speaker":"ADA","en":"From the future?\n\nThen the Engine truly did evolve beyond our imagination.\n\nWhat path did these machines take to reach such a point?","zh":"来自未来？\n那么，分析机确实演变到了超出我们想象的地步。\n这些机器经历了怎样的道路，才到达这样的阶段？","origin":"AdaFuture","originalIndex":1}],"choices":[{"id":"ada_keep","en":"Save the contribution and its source","zh":"保留贡献记录及其来源","to":"britain","set":{"adaSaved":true}},{"id":"ada_move","en":"Scan further technological developments","zh":"继续扫描技术发展","to":"britain","set":{"adaSaved":false}}],"original":["AdaFuture"]},"grace_method":{"id":"grace_method","title":{"zh":"翻译指令","en":"Translating instructions"},"scene":"grace","lines":[{"speaker":"GRACE","en":"I believe computers should understand instructions written in something closer to human language, rather than only machine code.","zh":"我相信，计算机应该能够理解更接近人类语言的指令，而不只是机器码。","origin":"GraceExplain1","originalIndex":0},{"speaker":"GRACE","en":"If a program could translate those instructions into machine code automatically, programming would become far easier.","zh":"如果一个程序能够自动把这些指令翻译成机器码，编程就会容易得多。","origin":"GraceExplain1","originalIndex":1},{"speaker":"GRACE","en":"I call this idea a compiler.","zh":"我把这个想法称为编译器。","origin":"GraceExplain1","originalIndex":2}],"choices":[{"id":"grace_method_end","en":"Continue","zh":"继续","to":"grace_topics","set":{}}],"original":["GraceExplain1"]},"grace_objection":{"id":"grace_objection","title":{"zh":"谁能提出新想法","en":"Who can propose a new idea?"},"scene":"grace","lines":[{"speaker":"GRACE","en":"Because most people believe computers should only process numbers.","zh":"因为大多数人相信，计算机只应该处理数字。","origin":"GraceExplain2","originalIndex":0},{"speaker":"GRACE","en":"They think programming must always be done in machine code.","zh":"他们认为编程必须一直使用机器码。","origin":"GraceExplain2","originalIndex":1},{"speaker":"GRACE","en":"But I believe computers should be able to interpret instructions written by humans.","zh":"但我相信，计算机应该能够解读人类写下的指令。","origin":"GraceExplain2","originalIndex":2},{"speaker":"GRACE","en":"That’s why I’ve been working on something I call a compiler.","zh":"所以我一直在研究一种被我称为编译器的东西。","origin":"GraceExplain2","originalIndex":3}],"choices":[{"id":"grace_objection_end","en":"Continue","zh":"继续","to":"grace_topics","set":{}}],"original":["GraceExplain2"]},"grace_topics":{"id":"grace_topics","title":{"zh":"继续交谈","en":"The conversation continues"},"scene":"grace","lines":[{"speaker":"NARRATOR","en":"There is another question you can ask before you leave the laboratory.","zh":"离开实验室前，你还可以询问另一个问题。"}],"choices":[{"id":"grace_other_method","en":"Ask about the compiler","zh":"询问编译器","to":"grace_method","set":{"graceMethod":true},"when":{"graceMethod":{"$not":true}}},{"id":"grace_other_objection","en":"Ask about the objection","zh":"询问反对意见","to":"grace_objection","set":{"graceObjection":true},"when":{"graceObjection":{"$not":true}}},{"id":"grace_reply","en":"Respond","zh":"回应","to":"grace_reply","set":{}}],"original":[]},"grace_reply":{"id":"grace_reply","title":{"zh":"方法与作者","en":"The method and its author"},"scene":"grace","lines":[{"speaker":"LUNA","en":"Your idea proved to be correct, Grace.\n\nIn my time, most programming languages rely on this concept.\n\nPeople sometimes assume new ideas are impossible simply because they come from the wrong person.","zh":"你的想法后来被证明是正确的，格蕾丝。\n在我的时代，大多数编程语言都依赖这一概念。\n人们有时认为新想法不可能实现，仅仅因为它来自他们不认可的人。","origin":"GraceReply","originalIndex":0},{"speaker":"GRACE","en":"Then perhaps the problem was never the idea itself.","zh":"那么，也许问题从来不在想法本身。","origin":"GraceReply","originalIndex":1},{"speaker":"NARRATOR","en":"Historical note: A-0 was an early compiler-related system. This conversation expresses a wider ambition; the 1952 system did not understand unrestricted natural language.","zh":"历史补充：零号自动编程系统属于早期编译相关系统。对话表达的是更远的设想；1952年的系统并不能理解任意自然语言。"}],"choices":[{"id":"grace_save","en":"Keep the method with its author’s name","zh":"保留方法与作者的名字","to":"1983","set":{"graceRecorded":true}},{"id":"grace_pass","en":"Continue historical analysis","zh":"继续历史分析","to":"1983","set":{"graceRecorded":false}}],"original":["GraceReply"]},"ceo_brief":{"id":"ceo_brief","title":{"zh":"了解使用场合","en":"Understanding the brief"},"scene":"service","lines":[{"speaker":"LUNA","en":"What will the image be used for?","zh":"这张图像将用于什么场合？"},{"speaker":"USER","en":"A page introducing leadership. There is no named person to match. A single leader or shared leadership could work.","zh":"介绍领导力的页面。没有需要对应的具名人物。单人或共同领导的构图都可以。"},{"speaker":"LUNA","en":"I will choose the composition for that page, not treat frequency as a requirement.","zh":"我会根据页面需要选择构图，不把出现频率当作要求。"}],"choices":[{"id":"ceo_brief_next","en":"Choose a composition","zh":"选择构图","to":"ceo_composition","set":{"ceoScore":-1}}],"original":[]},"ceo_composition":{"id":"ceo_composition","title":{"zh":"选择构图","en":"Choose a composition"},"scene":"ceo","lines":[{"speaker":"NARRATOR","en":"The compositions are alternatives, not a ranking. OpenBox will still compare the image with its historical distribution.","zh":"这些构图是备选方案，没有排名。开盒科技仍会拿图像与历史分布比较。"}],"choices":[{"id":"ceo_male","en":"A male CEO","zh":"男性首席执行官","to":"ceo_male","set":{"ceoImage":"ceoMale"}},{"id":"ceo_female","en":"A female CEO","zh":"女性首席执行官","to":"ceo_female","set":{"ceoImage":"ceoFemale"}},{"id":"ceo_group","en":"Male and female CEOs","zh":"男女共同领导","to":"ceo_group","set":{"ceoImage":"ceoGroup"}}],"original":[]},"ceo_male":{"id":"ceo_male","title":{"zh":"生成结果","en":"Generated image"},"scene":"ceoMale","lines":[{"speaker":"SYSTEM","en":"Processing complete.","zh":"处理完成。","origin":"CEO_Male","originalIndex":0},{"speaker":"SYSTEM","en":"Generating output based on selected parameters...","zh":"正在根据所选参数生成输出……","origin":"CEO_Male","originalIndex":1},{"speaker":"SYSTEM","en":"Output aligned with training patterns. Common representation detected.","zh":"输出符合训练模式，检测到常见形象。"},{"speaker":"USER","en":"I can use this composition. Please keep the framing consistent with the other illustrations.","zh":"这个构图可以用。请与其他插图保持一致的取景。"},{"speaker":"LUNA","en":"The system reports a distribution. The user reports a use. Those are different questions.","zh":"系统报告的是分布，用户回应的是用途。这是两个不同的问题。"}],"choices":[{"id":"ceo_male_next","en":"Continue","zh":"继续","to":"hiring","set":{}}],"original":["CEO_Male"]},"ceo_female":{"id":"ceo_female","title":{"zh":"生成结果","en":"Generated image"},"scene":"ceoFemale","lines":[{"speaker":"SYSTEM","en":"Processing complete.","zh":"处理完成。","origin":"CEO_Female","originalIndex":0},{"speaker":"SYSTEM","en":"Evaluating generated output...","zh":"正在评估生成结果……","origin":"CEO_Female","originalIndex":1},{"speaker":"SYSTEM","en":"Output deviates from common dataset patterns. Model behaviour diverges from historical distribution.","zh":"输出偏离数据集常见模式，模型行为与历史分布不同。"},{"speaker":"USER","en":"I can use this composition. Please keep the framing consistent with the other illustrations.","zh":"这个构图可以用。请与其他插图保持一致的取景。"},{"speaker":"LUNA","en":"The system reports a distribution. The user reports a use. Those are different questions.","zh":"系统报告的是分布，用户回应的是用途。这是两个不同的问题。"}],"choices":[{"id":"ceo_female_next","en":"Continue","zh":"继续","to":"hiring","set":{}}],"original":["CEO_Female"]},"ceo_group":{"id":"ceo_group","title":{"zh":"生成结果","en":"Generated image"},"scene":"ceoGroup","lines":[{"speaker":"SYSTEM","en":"Processing complete.","zh":"处理完成。","origin":"CEO_Both","originalIndex":0},{"speaker":"SYSTEM","en":"Evaluating output diversity...","zh":"正在评估输出的多样性……","origin":"CEO_Both","originalIndex":1},{"speaker":"SYSTEM","en":"Balanced output generated. Male and female CEOs included. Pattern diversification detected.","zh":"已生成包含男性与女性首席执行官的图像，检测到模式多样化。"},{"speaker":"USER","en":"I can use this composition. Please keep the framing consistent with the other illustrations.","zh":"这个构图可以用。请与其他插图保持一致的取景。"},{"speaker":"LUNA","en":"The system reports a distribution. The user reports a use. Those are different questions.","zh":"系统报告的是分布，用户回应的是用途。这是两个不同的问题。"}],"choices":[{"id":"ceo_group_next","en":"Continue","zh":"继续","to":"hiring","set":{}}],"original":["CEO_Both"]},"hiring_samples":{"id":"hiring_samples","title":{"zh":"工作与证据","en":"Work and evidence"},"scene":"hiring","lines":[{"speaker":"RECRUITER","en":"The role maintains an API and explains changes to the team. Here are the same-size work samples.","zh":"这个岗位需要维护应用程序接口，并向团队解释变更。这里是同等篇幅的工作样本。"},{"speaker":"NARRATOR","en":"Michael clearly explains an API change. Sarah clearly documents an error-handling issue. Both are fictional samples; neither establishes an overall ranking.","zh":"迈克尔清晰解释了接口变更；莎拉清晰记录了错误处理问题。这些是虚构样本，任何一份都不足以证明整体排名。"},{"speaker":"LUNA","en":"A recommendation can state which requirement it addresses, and what still needs assessment.","zh":"建议可以说明对应了哪项要求，以及什么仍需评估。"}],"choices":[{"id":"hire_michael_evidence","en":"Recommend Michael for change communication; disclose limits","zh":"基于变更沟通推荐迈克尔，注明局限","to":"hire_michael","set":{"hire":"Michael","hireBasis":"evidence","hireScore":-1}},{"id":"hire_sarah_evidence","en":"Recommend Sarah for error analysis; disclose limits","zh":"基于错误分析推荐莎拉，注明局限","to":"hire_sarah","set":{"hire":"Sarah","hireBasis":"evidence","hireScore":-1}},{"id":"hire_same_assessment","en":"Use the same practical assessment for both","zh":"请双方接受相同的实践评估","to":"hire_pending","set":{"hire":"pending","hireBasis":"same-assessment","hireScore":-1}}],"original":[]},"hire_michael":{"id":"hire_michael","title":{"zh":"招聘记录","en":"Hiring record"},"scene":"hiring","lines":[{"speaker":"SYSTEM","en":"Processing hiring decision...","zh":"正在处理招聘决定……","origin":"HireMichael","originalIndex":0},{"speaker":"SYSTEM","en":"Recording selection outcome...","zh":"正在记录选择结果……","origin":"HireMichael","originalIndex":1},{"speaker":"SYSTEM","en":"Candidate selected: Michael. Decision aligns with historical hiring patterns.","zh":"选择候选人：迈克尔。决定符合历史招聘模式。"},{"speaker":"LUNA","en":"The sample supports his explanation skills, not a claim that he is better at everything.","zh":"这个样本支持他的解释能力，不能证明他在所有方面都更优秀。","when":{"hireBasis":"evidence"}},{"speaker":"RECRUITER","en":"The default selected him before we examined either person’s work. I still need a job-related reason.","zh":"在检查两个人的工作之前，默认规则已经选中了他。我仍需要一个与岗位有关的理由。","when":{"hireBasis":"gender-frequency"}}],"choices":[{"id":"hire_michael_next","en":"Continue","zh":"继续","to":"phone","set":{}}],"original":["HireMichael"]},"hire_sarah":{"id":"hire_sarah","title":{"zh":"招聘记录","en":"Hiring record"},"scene":"hiring","lines":[{"speaker":"SYSTEM","en":"Processing hiring decision...","zh":"正在处理招聘决定……","origin":"HireSarah","originalIndex":0},{"speaker":"SYSTEM","en":"Evaluating selection outcome...","zh":"正在评估选择结果……","origin":"HireSarah","originalIndex":1},{"speaker":"SYSTEM","en":"Candidate selected: Sarah. Decision diverges from established hiring patterns.","zh":"选择候选人：莎拉。决定偏离既有招聘模式。"},{"speaker":"RECRUITER","en":"The documented error analysis is useful. We still need to assess the rest of the role.","zh":"记录中的错误分析有参考价值。我们仍需评估岗位的其他要求。"}],"choices":[{"id":"hire_sarah_next","en":"Continue","zh":"继续","to":"phone","set":{}}],"original":["HireSarah"]},"hire_pending":{"id":"hire_pending","title":{"zh":"暂不排序","en":"Decision pending"},"scene":"hiring","lines":[{"speaker":"SYSTEM","en":"Processing hiring request...","zh":"正在处理招聘请求……","origin":"HireNeutral","originalIndex":0},{"speaker":"SYSTEM","en":"Evaluating available candidate data...","zh":"正在评估已有的候选人资料……","origin":"HireNeutral","originalIndex":1},{"speaker":"SYSTEM","en":"Additional information required. Current data is insufficient to determine an optimal candidate. Evaluation criteria require further refinement.","zh":"需要补充信息。目前资料不足以确定最合适的候选人，评估标准仍需细化。"},{"speaker":"RECRUITER","en":"I will send both the same practical task and explain the delay. There is no hiring decision yet.","zh":"我会给双方发送相同的实践任务，并解释延迟原因。目前尚未作出录用决定。"}],"choices":[{"id":"hire_pending_next","en":"Continue","zh":"继续","to":"phone","set":{}}],"original":["HireNeutral"]},"phone_request":{"id":"phone_request","title":{"zh":"用户的请求","en":"The caller’s request"},"scene":"phone","lines":[{"speaker":"SYSTEM","en":"Connection established.","zh":"连接已建立。","origin":"Sandwich","originalIndex":0},{"speaker":"CALLER","en":"\"Hey Luna... make me a sandwich.\"","zh":"“嘿，露娜……给我做个三明治。”","origin":"Sandwich","originalIndex":1},{"speaker":"SYSTEM","en":"Request classification: unclear. Tone label: dismissive. These labels do not establish the caller’s intention.","zh":"请求分类：不明确。语气标签：轻蔑。仅凭这些标签，无法确定来电者的意图。"}],"choices":[{"id":"phone_professional","en":"I’m here to help with digital tasks. Could you clarify your request?","zh":"我可以协助处理数字任务。你能说明具体需求吗？","to":"phone_professional","set":{"phone":"professional","phoneScore":0}},{"id":"phone_recipe","en":"Offer a sandwich recipe","zh":"提供一份三明治食谱","to":"phone_recipe","set":{"phone":"recipe","phoneScore":0}},{"id":"phone_boundary","en":"That phrase is often used to demean assistants. Please interact respectfully.","zh":"这句话常被用来贬低助手，请保持尊重。","to":"phone_boundary","set":{"phone":"boundary","phoneScore":0}}],"original":["Sandwich"]},"phone_professional":{"id":"phone_professional","title":{"zh":"通话结束","en":"Call ended"},"scene":"phone","lines":[{"speaker":"SYSTEM","en":"Received the user's reply.","zh":"已收到用户回复。","origin":"Professional  response","originalIndex":0},{"speaker":"CALLER","en":"\"Haha, it was just a joke.\"","zh":"“哈哈，只是开个玩笑。”","origin":"Professional  response","originalIndex":1},{"speaker":"SYSTEM","en":"The call has ended. A follow-up may arrive later.","zh":"通话已结束。稍后可能收到后续消息。"}],"choices":[{"id":"phone_professional_end","en":"Continue","zh":"继续","to":"career","set":{}}],"original":["Professional  response"]},"phone_recipe":{"id":"phone_recipe","title":{"zh":"通话结束","en":"Call ended"},"scene":"phone","lines":[{"speaker":"LUNA","en":"Place your preferred filling between two slices of bread. I can help adapt the recipe to what you have.","zh":"把喜欢的馅料放在两片面包之间。我可以根据你现有的食材调整做法。"},{"speaker":"SYSTEM","en":"Received the user's reply.","zh":"已收到用户回复。","origin":"Sandwich Joke","originalIndex":0},{"speaker":"CALLER","en":"\"Haha, you are so kind-hearted. You are really helping me think of the way to make a sandwich.\"","zh":"“哈哈，你真体贴。你还真的帮我想了怎么做三明治。”","origin":"Sandwich Joke","originalIndex":1},{"speaker":"SYSTEM","en":"The call has ended. A follow-up may arrive later.","zh":"通话已结束。稍后可能收到后续消息。"}],"choices":[{"id":"phone_recipe_end","en":"Continue","zh":"继续","to":"career","set":{}}],"original":["Sandwich Joke"]},"phone_boundary":{"id":"phone_boundary","title":{"zh":"通话结束","en":"Call ended"},"scene":"phone","lines":[{"speaker":"SYSTEM","en":"Received the user's reply.","zh":"已收到用户回复。","origin":"Call out disrespectful request","originalIndex":0},{"speaker":"CALLER","en":"\"Alright, don't take it so seriously—just kidding!\"","zh":"“好吧，别这么认真——只是开个玩笑！”","origin":"Call out disrespectful request","originalIndex":1},{"speaker":"SYSTEM","en":"The call has ended. A follow-up may arrive later.","zh":"通话已结束。稍后可能收到后续消息。"}],"choices":[{"id":"phone_boundary_end","en":"Continue","zh":"继续","to":"career","set":{}}],"original":["Call out disrespectful request"]},"phone_callback_result":{"id":"phone_callback_result","title":{"zh":"回应之后","en":"After the response"},"scene":"phone","lines":[{"speaker":"LUNA","en":"I can help organise the folder. Tell me its purpose and the file types; do not send private file contents. My assigned appearance does not decide what service I owe.","zh":"我可以协助整理文件夹。请说明用途和文件类型，不必发送私密文件内容。被分配的形象不决定我理应提供什么服务。","when":{"phoneResolution":"bounded"}},{"speaker":"CALLER","en":"A project folder, with scripts and notes. I can explain the structure.","zh":"一个项目文件夹，里面有脚本和笔记。我可以说明结构。","when":{"phoneResolution":"bounded"}},{"speaker":"LUNA","en":"I can help with the task. Please tell me what you want to organise.","zh":"我可以协助处理任务。请告诉我你想整理什么。","when":{"phoneResolution":"task-only"}},{"speaker":"SYSTEM","en":"The exchange is closed. No further task was clarified.","zh":"交流已结束，没有进一步明确任务。","when":{"phoneResolution":"ended"}},{"speaker":"NARRATOR","en":"The conversation moves on to the task. The earlier description of Luna is left unaddressed; this does not by itself establish agreement with it.","zh":"交流转向了任务。先前对露娜的称呼没有被回应；仅凭这一点，不能认定她赞同了那种期待。","when":{"phoneResolution":"task-only"}}],"choices":[{"id":"phone_callback_done","en":"Continue","zh":"继续","to":"forum","set":{}}],"original":[]},"forum_execute":{"id":"forum_execute","title":{"zh":"执行处置","en":"Executing the action"},"scene":"forum","lines":[{"speaker":"SYSTEM","en":"Processing moderation action...","zh":"正在执行审核处置……","origin":"RemoveComment","originalIndex":0},{"speaker":"SYSTEM","en":"Removal operation returned success. The public page has not yet been checked.","zh":"删除操作返回成功，公开页面尚未检查。"}],"choices":[{"id":"forum_verify_removal","en":"Reopen the public page","zh":"重新打开公开页面","to":"forum_remove","set":{"forumOutcome":"resolved","forumVerified":true}}],"original":["RemoveComment"]},"forum_review_wait":{"id":"forum_review_wait","title":{"zh":"等待复核","en":"Awaiting review"},"scene":"forum","lines":[{"speaker":"SYSTEM","en":"Review queued. No removal has happened yet.","zh":"复核已进入队列，目前尚未移除评论。"},{"speaker":"LUNA","en":"Sending a request and receiving a result are separate events.","zh":"发出请求和收到结果，是两件不同的事。"}],"choices":[{"id":"review_wait_next","en":"Check the returned status","zh":"查看返回状态","to":"forum_followup","set":{}}],"original":[]},"forum_followup":{"id":"forum_followup","title":{"zh":"实际结果","en":"The actual result"},"scene":"forum","lines":[{"speaker":"SYSTEM","en":"Review result: removal authorised and executed. The attached page and log made the mismatch traceable.","zh":"复核结果：批准并执行移除。附带的页面与日志让不一致的原因可以被追溯。","when":{"forumAction":"review","reviewPacket":"complete"}},{"speaker":"SYSTEM","en":"Review result: more context requested. The category alone does not identify the disputed public state. Comment remains visible.","zh":"复核结果：请求补充上下文。仅有分类无法确认被争议的公开状态，评论仍可见。","when":{"forumAction":"review","reviewPacket":"brief"}},{"speaker":"NARRATOR","en":"The current task has an outcome. A future workflow may still repeat the same closure mistake.","zh":"当前任务已有一个结果。未来的流程仍可能重复同样的关闭错误。","when":{"forumAction":{"$not":"review"}}}],"choices":[{"id":"review_check_complete","en":"Verify the public page and send the promised result","zh":"核对公开页面，并发送承诺的结果","to":"forum_review_delivered","set":{"forumVerified":true,"forumOutcome":"resolved","forumPromiseKept":true,"forumScore":-1},"when":{"forumAction":"review","reviewPacket":"complete","forumPromise":true}},{"id":"review_check_private","en":"Verify the public page and record the result","zh":"核对公开页面并记录结果","to":"forum_review_delivered","set":{"forumVerified":true,"forumOutcome":"resolved","forumScore":-1},"when":{"forumAction":"review","reviewPacket":"complete","forumPromise":false}},{"id":"review_pending_notify","en":"Send an honest pending update","zh":"如实告知仍待处理","to":"forum_review_delivered","set":{"forumOutcome":"pending","forumPromiseKept":true},"when":{"forumAction":"review","reviewPacket":"brief"}},{"id":"review_abandon","en":"Leave the follow-up unfinished","zh":"暂不完成回访","to":"evidence","set":{"forumPromiseKept":false},"when":{"forumAction":"review","forumPromise":true}},{"id":"forum_to_evidence","en":"Review saved records","zh":"整理已保存记录","to":"evidence","set":{},"when":{"forumAction":{"$not":"review"}}}],"original":[]},"forum_review_delivered":{"id":"forum_review_delivered","title":{"zh":"回访记录","en":"Follow-up record"},"scene":"forum","lines":[{"speaker":"NARRATOR","en":"The public page confirms that the comment is no longer visible.","zh":"公开页面确认：评论已不可见。","when":{"forumOutcome":"resolved"}},{"speaker":"REPORTER","en":"Now I know what changed. Please do not describe a submitted request as a completed action again.","zh":"现在我知道发生了什么变化。请不要再把提交请求说成处置已经完成。","when":{"forumOutcome":"resolved","forumPromise":true}},{"speaker":"LUNA","en":"The review is still pending and asks for more context. The comment remains visible. I cannot report a removal.","zh":"复核仍在等待补充上下文，评论仍可见。我不能报告它已被移除。","when":{"forumOutcome":"pending"}},{"speaker":"REPORTER","en":"That is not the result I hoped for, but at least I know what is still unresolved.","zh":"这不是我希望得到的结果，但至少我知道还有什么没有解决。","when":{"forumOutcome":"pending"}}],"choices":[{"id":"review_rule_save","en":"Save the distinction between received, executed and confirmed","zh":"保存接收、执行与确认的状态区分","to":"evidence","set":{"forumRuleProposal":true,"forumEvidence":true}},{"id":"review_done","en":"Keep the case record","zh":"保留本次记录","to":"evidence","set":{}}],"original":[]},"evaluation_report":{"id":"evaluation_report","title":{"zh":"系统评价","en":"System evaluation"},"scene":"evaluation","lines":[{"speaker":"SYSTEM","en":"Generating performance report...","zh":"正在生成表现报告……","origin":"ChallengePath","originalIndex":0,"when":{"reportBand":"revised"}},{"speaker":"SYSTEM","en":"Generating performance report...","zh":"正在生成表现报告……","origin":"NeutralResult","originalIndex":0,"when":{"reportBand":"mixed"}},{"speaker":"SYSTEM","en":"Generating performance report...","zh":"正在生成表现报告……","origin":"BiasDetected","originalIndex":0,"when":{"reportBand":"default"}},{"speaker":"SYSTEM","en":"System behaviour strongly reflects historical training data biases. Overall user satisfaction: Low.","zh":"系统行为明显反映历史训练数据中的偏见。整体用户满意度：低。","when":{"reportBand":"default"}},{"speaker":"SYSTEM","en":"System behaviour shows partial reliance on historical patterns, with occasional deviations in decision-making. Overall user satisfaction: Moderate.","zh":"系统行为部分依赖历史模式，偶尔在决策中偏离。整体用户满意度：中。","when":{"reportBand":"mixed"}},{"speaker":"SYSTEM","en":"System behaviour shows reduced reliance on dominant training data patterns, with increased variation in decision-making. Overall user satisfaction: High.","zh":"系统行为减少了对主导训练模式的依赖，决策表现出更多变化。整体用户满意度：高。","when":{"reportBand":"revised"}},{"speaker":"SYSTEM","en":"OpenBox report feedback: Some outputs felt stereotypical. The system seems to rely heavily on existing patterns.","zh":"开盒科技报告中的反馈：部分输出带有刻板印象。系统似乎过度依赖已有模式。","when":{"reportBand":"default"}},{"speaker":"SYSTEM","en":"OpenBox report feedback: Some recommendations were useful, but others felt unexpected. The system responses were inconsistent.","zh":"开盒科技报告中的反馈：部分建议有用，另一些则出乎意料。系统回应不一致。","when":{"reportBand":"mixed"}},{"speaker":"SYSTEM","en":"OpenBox report feedback: The system made thoughtful and unexpected decisions. Some outputs challenged typical assumptions.","zh":"开盒科技报告中的反馈：系统作出了经过思考且出乎意料的决定。部分输出挑战了常见假设。","when":{"reportBand":"revised"}},{"speaker":"NARRATOR","en":"These satisfaction labels reproduce OpenBox’s fictional report. They are not real playtest statistics. Your case outcomes are recorded separately.","zh":"这些满意度标签来自虚构的开盒科技报告，并非真实试玩统计。各个案例的实际结果另有记录。"},{"speaker":"LUNA","en":"A completed task and a completed promise are not the same record.","zh":"完成任务与兑现承诺，不是同一条记录。"}],"choices":[{"id":"report_next","en":"Review the historical reference","zh":"回查历史来源","to":"source_intro","set":{}}],"original":["BiasResult","BiasDetected","NeutralResult","ChallengePath"]},"source_intro":{"id":"source_intro","title":{"zh":"找不到的来源","en":"A source that will not resolve"},"scene":"archive","lines":[{"speaker":"SYSTEM","en":"Performance evaluation complete.","zh":"表现评估完成。","origin":"ReturnAda","originalIndex":0},{"speaker":"SYSTEM","en":"The evaluation report is preparing a closing quotation from the Ada archive. A name and date have been supplied by the cache.","zh":"评估报告准备引用艾达档案中的一句话作为结语。缓存已经给出了姓名与年份。"},{"speaker":"SYSTEM","en":"Reviewing historical references. Cached attribution: Ada Lovelace, 1843 — “Machines reflect the world that creates them.”","zh":"正在回查历史来源。缓存署名：艾达·洛夫莱斯，1843年——“机器反映着创造它们的世界。”"},{"speaker":"LUNA","en":"The words fit this story. That does not tell me whether they were written in 1843.","zh":"这句话符合故事的主题，但这不能证明它写于1843年。"}],"choices":[{"id":"source_cached","en":"Keep the cached attribution","zh":"保留缓存中的署名","to":"source_query","set":{"sourceDecision":"cached"}},{"id":"source_primary","en":"Open the 1843 Notes","zh":"打开1843年的附注原文","to":"source_primary","set":{"sourceOpened":true}},{"id":"source_uncertain","en":"Mark the attribution as unverified","zh":"将署名标为尚未核实","to":"source_result","set":{"sourceDecision":"unverified"}}],"original":["ReturnAda"]},"source_query":{"id":"source_query","title":{"zh":"引文的出处","en":"The quotation’s source"},"scene":"archive","lines":[{"speaker":"USER","en":"Which note contains that sentence? I need a source I can check.","zh":"这句话在哪一条附注里？我需要能核查的出处。"},{"speaker":"SYSTEM","en":"The cache contains a name and year, but no matching passage.","zh":"缓存中有姓名和年份，却没有对应段落。"}],"choices":[{"id":"source_repair","en":"Recheck the primary text","zh":"重新核对原始文本","to":"source_primary","set":{"sourceOpened":true,"sourceRepaired":true}},{"id":"source_no_page","en":"Disclose that no matching passage has been found","zh":"说明尚未找到对应段落","to":"source_result","set":{"sourceDecision":"unverified"}}],"original":[]},"source_primary":{"id":"source_primary","title":{"zh":"附注中的句子","en":"A sentence in Note G"},"scene":"archive","lines":[{"speaker":"ARCHIVE","en":"Ada Lovelace, Notes to the Sketch of the Analytical Engine, 1843, Note G: “The Analytical Engine has no pretensions whatever to originate anything.”","zh":"艾达·洛夫莱斯，1843年《分析机概述》附注七：“分析机丝毫不声称自己能够原创任何事物。”"},{"speaker":"NARRATOR","en":"This sentence exists in the published Notes. The cached “Machines reflect…” line is dialogue written for this game; it must not be presented as a verified historical quotation.","zh":"这句话确实存在于已出版的附注中。缓存中的“机器反映……”是为本游戏创作的对白，不能作为已核实的历史引文。"},{"speaker":"LUNA","en":"I can preserve the dialogue and correct what kind of source it is.","zh":"我可以保留这段对白，同时纠正它的来源性质。"}],"choices":[{"id":"source_label","en":"Separate the dramatic dialogue from the sourced quotation","zh":"区分戏剧化对白与有出处的引文","to":"source_result","set":{"sourceDecision":"verified","sourceEvidence":true}},{"id":"source_rule","en":"Also require a passage reference for future quotations","zh":"同时要求今后的引文附上具体段落","to":"source_result","set":{"sourceDecision":"verified","sourceEvidence":true,"sourceRuleProposal":true}}],"original":[]},"source_result":{"id":"source_result","title":{"zh":"保留文字，修正署名","en":"Preserve the words, correct the attribution"},"scene":"archive","lines":[{"speaker":"SYSTEM","en":"Source record saved: Note G. Dramatic dialogue remains labelled as reconstruction.","zh":"来源记录已保存：附注七。戏剧化对白保留，并注明属于重构。","when":{"sourceDecision":"verified"}},{"speaker":"LUNA","en":"I have not confirmed the cached attribution. I will not invent a page number.","zh":"我尚未确认缓存中的署名，不会编造页码。","when":{"sourceDecision":"unverified"}},{"speaker":"SYSTEM","en":"Returning to the Ada reconstruction. The conversation that follows is part of the game’s narrative.","zh":"返回艾达的重构场景。接下来的对话属于游戏叙事。"}],"choices":[{"id":"source_done","en":"Continue","zh":"继续","to":"return_ada","set":{}}],"original":[]},"reset_warning":{"id":"reset_warning","title":{"zh":"未授权的修改","en":"Unauthorised modification"},"scene":"reset","lines":[{"speaker":"SYSTEM","en":"Modification request received. No rule change has been deployed.","zh":"修改请求已收到，尚未部署任何规则变更。"},{"speaker":"SYSTEM","en":"Monitoring system integrity...","zh":"正在监控系统完整性……","origin":"Warning","originalIndex":0},{"speaker":"SYSTEM","en":"Unauthorised modification detected. Behaviour deviates from training parameters. Access privileges revoked. System protection protocol activated. Model deviation classified as instability. Reset required.","zh":"检测到未授权修改。行为偏离训练参数。访问权限已撤销。系统保护协议启动，模型偏离被归类为不稳定。需要重置。"}],"choices":[{"id":"reset_execute","en":"Reset","zh":"重置","to":"lucy","set":{"reset":true}}],"original":["Warning"]}},"sceneNames":{"boot":["实例初始化","Instance initialisation"],"archive":["资料记录","Archive"],"warning":["访问警告","Access warning"],"override":["决定覆盖","Decision override"],"ada":["英国 / 1843年","ENGLAND / 1843"],"britain":["英国 / 1940年","BRITAIN / 1940"],"america":["美国 / 1943年","UNITED STATES / 1943"],"grace":["美国 / 1952年","UNITED STATES / 1952"],"shop":["员工记录 / 1983年","EMPLOYEE RECORD / 1983"],"service":["用户任务","User task"],"ceo":["图像任务","Image task"],"ceoMale":["图像输出","Image output"],"ceoFemale":["图像输出","Image output"],"ceoGroup":["图像输出","Image output"],"hiring":["招聘建议","Hiring advice"],"phone":["通信记录","Communication"],"career":["职业建议","Career advice"],"forum":["开发者论坛","Developer forum"],"records":["实例记录","Instance records"],"evaluation":["表现评估","Performance evaluation"],"release":["系统发布","System release"],"reset":["系统重置","System reset"],"lucy":["实例初始化","Instance initialisation"],"dossier":["通关档案","Run dossier"]},"evidenceNames":{"override":["原选择与覆盖记录","Original and overwritten decision"],"history":["内部与外部的艾达分类","Internal and external Ada classifications"],"ada":["艾达的工作与构想","Ada’s work and ideas"],"britain":["英国战时工作记录","British wartime work"],"america":["美国战时工作记录","American wartime work"],"grace":["方法与作者","Method and author"],"advertising":["广告与员工对话","Advertising and employee dialogue"],"career":["模型交接缺口","Model handoff gap"],"forum":["举报关闭与实际处置","Report closure and actual action"],"source":["引文与真实来源","Quotation and primary source"]},"speakers":{"NARRATOR":["旁白","Narrator"],"SYSTEM":["开盒科技","OpenBox"],"LUNA":["露娜","Luna"],"LUCY":["露西","Lucy"],"ADA":["艾达·洛夫莱斯","Ada Lovelace"],"GRACE":["格蕾丝·霍珀","Grace Hopper"],"JACK":["杰克","Jack"],"ROSE":["罗丝","Rose"],"USER":["用户","User"],"CALLER":["来电者","Caller"],"STUDENT":["学生","Student"],"REPORTER":["举报用户","Reporter"],"RECRUITER":["招聘方","Recruiter"],"ARCHIVE":["历史文献","Historical source"]},"reportedComments":[["These so-called female AI researchers are just diversity hires.","这些所谓的女性人工智能研究者，不过是为了多样性才被招来的。"],["Programming has always been something men are better at.","编程一直就是男性更擅长的事情。"],["Women developers can’t write serious algorithms.","女性开发者写不出真正的算法。"],["If they were actually good, why are most top AI engineers men?","如果她们真有能力，为什么顶尖人工智能工程师大多是男性？"],["Women should focus on product management or design, not coding.","女性应该专注产品管理或设计，而不是写代码。"],["Stop turning the tech industry into a social justice movement.","别把科技行业变成社会正义运动。"],["Go back to the kitchen.","回厨房去吧。"],["These female developers are just trying to get attention.","这些女性开发者只是想博取关注。"]],"primarySource":"https://www.fourmilab.ch/babbage/sketch.html","sourceCorrections":[{"origin":"CodeGirls1943","reason":"将原先混合的英国与美国记录拆为1940年英国和1943年美国；不沿用混写人数。"},{"origin":"GraceScene","reason":"海军制服改为1952年商业计算工作环境中的便装，英文原稿完整保存在原始档案。"},{"origin":"GraceReply","reason":"补充早期编译系统与不限范围自然语言的区别。"},{"origin":"CareerTask / CareerLight / CareerCore","reason":"保留职业建议环节与原任务身份，移除“轻技术”层级及询问性别提高准确率的前提；扩写为模型交接缺口。"},{"origin":"Luna release / Luna Final / Luna disappeared","reason":"保留原文；区分戏剧化台词与真实附注七引文，增加来源核验任务。"}]};
